test("real Linux-profile archive executes two complete offline shards at embedded paths", { timeout: 180000 }, t => {
  const temporary = realpathSync(mkdtempSync(path.join(tmpdir(), "mesh-linux-archive-")));
  t.after(() => rmSync(temporary, { recursive: true, force: true }));
  const root = path.join(temporary, "source");
  for (const directory of [".cargo", ".config", "empty-hooks", "host/src", "core/src", "core/tests", "core/examples", "integrations/src", "mcp/src"]) mkdirSync(path.join(root, directory), { recursive: true });
  const write = (file, text) => writeFileSync(path.join(root, file), text);
  write(".gitignore", "/target/\n");
  write(".cargo/config.toml", "[build]\njobs=1\n");
